        grid_x = (total_elements + block - 1) // block
        grid = (grid_x, 1, 1)

        ptx_launch(self.module, "conv2d_fp16", grid, (block, 1, 1), [
            x.data_ptr(),
            self.weight.data_ptr(),
            self.bias.data_ptr(),
            out.data_ptr()
        ])
        return out
